/**
 * Offline checks for the zlak-flow Gemini CLI extension.
 *
 * - gemini-extension.json is named zlak-flow, carries the package version and no secrets.
 * - commands/zlak-flow.toml parses back to the exact generated protocol.
 * - The prompt holds `{{args}}` once, at the end, and nothing Gemini would inject.
 * - The generated files are the copies from packages/core.
 */
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import { fileURLToPath } from "node:url";
import { gateLines } from "../../../scripts/check-parity.mjs";
import { parseToml } from "../../../scripts/lib/toml-subset.mjs";
import { appendInput, renderProtocol } from "../../../scripts/sync.mjs";

const root = fileURLToPath(new URL("..", import.meta.url));
const read = (path) => readFileSync(root + path, "utf8");

const manifest = JSON.parse(read("gemini-extension.json"));
const pkg = JSON.parse(read("package.json"));
const command = parseToml(read("commands/zlak-flow.toml"));

test("manifest is named zlak-flow, matches package.json and holds no secrets", () => {
  assert.equal(manifest.name, "zlak-flow");
  assert.equal(manifest.version, pkg.version);
  assert.ok(manifest.description.length > 40);
  for (const key of ["mcpServers", "settings", "contextFileName"]) {
    assert.ok(!(key in manifest), `${key} is not used`);
  }
});

test("the TOML parses back to exactly the rendered protocol", () => {
  assert.equal(
    command.prompt,
    appendInput(renderProtocol("gemini"), "{{args}}"),
  );
  assert.ok(command.description.length > 40);
});

test("the prompt takes {{args}} once, in the input section, and nothing is injected", () => {
  assert.equal(command.prompt.match(/\{\{args\}\}/g)?.length, 1);
  assert.ok(
    command.prompt.indexOf("{{args}}") >
      command.prompt.indexOf("## This run's input"),
  );
  assert.doesNotMatch(command.prompt, /!\{|@\{/, "no shell or file injection");
});

test("the five gate lines are present", () => {
  assert.equal(gateLines(command.prompt).length, 5);
});

test("generated files carry the shared sources", () => {
  JSON.parse(read("config/coder.example.json"));
  assert.match(
    read("commands/zlak-flow.toml"),
    /^# Generated by packages\/core/,
  );
});
